const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });

  // 1. Geometry & Time Definitions
  const reservoir_coords = [
    [-107.28, 33.15], [-107.13, 33.02], [-107.15, 32.96],
    [-107.25, 32.95], [-107.38, 33.02], [-107.36, 33.09],
    [-107.33, 33.13], [-107.28, 33.15]
  ];
  const geometry = ee.Geometry.Polygon(reservoir_coords);

  const date1_start = '1986-06-01';
  const date1_end = '1986-06-30';
  const date2_start = '2020-06-01';
  const date2_end = '2020-06-30';

  const scale = 30; // Landsat resolution in meters

  // Function to mask clouds in Landsat 5 SR data
  function maskL5sr(image) {
    // Bits 3 and 5 are cloud shadow and cloud, respectively.
    const qa = image.select('pixel_qa');
    const cloudShadowBitMask = (1 << 3);
    const cloudsBitMask = (1 << 5);
    // Both flags should be set to zero, indicating clear conditions.
    const mask = qa.bitwiseAnd(cloudShadowBitMask).eq(0)
      .and(qa.bitwiseAnd(cloudsBitMask).eq(0));
    return image.updateMask(mask).divide(10000)
      .select(['B2', 'B3', 'B4', 'B5', 'B7'], ['GREEN', 'RED', 'NIR', 'SWIR1', 'SWIR2'])
      .copyProperties(image, ['system:time_start']);
  }

  // Function to mask clouds in Landsat 8 SR data
  function maskL8sr(image) {
    // Bits 3, 5, 7, 8, 9, 10, 11
    // 3: cloud shadow, 5: cloud, 7: snow/ice, 8: water, 9: snow/ice, 10: cirrus, 11: cirrus
    const qa = image.select('pixel_qa');
    const cloudShadowBitMask = (1 << 3);
    const cloudsBitMask = (1 << 5);
    const snowIceBitMask = (1 << 7) | (1 << 9); // Bits 7 and 9 for snow/ice
    const cirrusBitMask = (1 << 10) | (1 << 11); // Bits 10 and 11 for cirrus

    const mask = qa.bitwiseAnd(cloudShadowBitMask).eq(0)
      .and(qa.bitwiseAnd(cloudsBitMask).eq(0))
      .and(qa.bitwiseAnd(snowIceBitMask).eq(0))
      .and(qa.bitwiseAnd(cirrusBitMask).eq(0));

    return image.updateMask(mask).divide(10000)
      .select(['B3', 'B4', 'B5', 'B6', 'B7'], ['GREEN', 'RED', 'NIR', 'SWIR1', 'SWIR2'])
      .copyProperties(image, ['system:time_start']);
  }

  // Function to calculate MNDWI
  function calculateMNDWI(image, greenBand, swir1Band) {
    return image.expression(
      '(GREEN - SWIR1) / (GREEN + SWIR1)', {
        'GREEN': image.select(greenBand),
        'SWIR1': image.select(swir1Band)
      }).rename('MNDWI');
  }

  // Function to get water area
  async function getWaterArea(collection, startDate, endDate, maskFunction, greenBand, swir1Band, collectionName) {
    let col = ee.ImageCollection(collection)
      .filterBounds(geometry)
      .filterDate(startDate, endDate)
      .map(maskFunction);

    const size = await col.size().getInfo();
    if (size === 0) {
      console.log(`${collectionName} Images (${startDate} to ${endDate}): ${size}`);
      return { area: null, count: 0, msg: `No images found for ${collectionName} in the specified date range (${startDate} to ${endDate}).` };
    }

    // Take the least cloudy image within the date range
    let image = col.sort('CLOUD_COVER').first();

    // Clip to geometry
    image = image.clip(geometry);

    const mndwi = calculateMNDWI(image, greenBand, swir1Band);
    const waterMask = mndwi.gt(0).selfMask(); // Threshold for water detection

    const count = await waterMask.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: geometry,
      scale: scale,
      maxPixels: 1e9
    }).get('MNDWI').getInfo();

    if (count === 0 || count === null) {
      console.log(`${collectionName} Images (${startDate} to ${endDate}): 1 (Val: 0.0)`);
      return { area: 0, count: 0, msg: `No valid water pixels found after masking for ${collectionName}.` };
    }

    const waterAreaSqM = waterMask.multiply(ee.Image.pixelArea()).reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: geometry,
      scale: scale,
      maxPixels: 1e9
    }).get('MNDWI').getInfo();

    console.log(`${collectionName} Images (${startDate} to ${endDate}): 1 (Val: ${count})`);

    if (waterAreaSqM === null) {
      return { area: null, count: count, msg: `Calculation failure for water area in ${collectionName}.` };
    }

    return { area: waterAreaSqM / 1e6, count: count, msg: null }; // Convert to Sq Km
  }

  // 2. Data Acquisition & Check for 1986 (Landsat 5)
  const result1986 = await getWaterArea(
    'LANDSAT/LT05/C01/T1_SR', date1_start, date1_end, maskL5sr, 'GREEN', 'SWIR1', 'Landsat 5'
  );

  if (result1986.area === null && result1986.count === 0) {
    console.log(result1986.msg);
    console.log('C1');
    return;
  }
  if (result1986.area === null && result1986.count > 0) {
    console.log(result1986.msg);
    console.log('C3');
    return;
  }
  if (result1986.area === 0 && result1986.count === 0) {
    console.log(result1986.msg);
    console.log('C2');
    return;
  }

  // 3. Data Acquisition & Check for 2020 (Landsat 8)
  const result2020 = await getWaterArea(
    'LANDSAT/LC08/C01/T1_SR', date2_start, date2_end, maskL8sr, 'GREEN', 'SWIR1', 'Landsat 8'
  );

  if (result2020.area === null && result2020.count === 0) {
    console.log(result2020.msg);
    console.log('C1');
    return;
  }
  if (result2020.area === null && result2020.count > 0) {
    console.log(result2020.msg);
    console.log('C3');
    return;
  }
  if (result2020.area === 0 && result2020.count === 0) {
    console.log(result2020.msg);
    console.log('C2');
    return;
  }

  // 4. Comparison and Final Answer
  const area1986 = result1986.area;
  const area2020 = result2020.area;

  console.log(`Water extent 1986: ${area1986.toFixed(2)} sq km, Pixels: ${result1986.count}`);
  console.log(`Water extent 2020: ${area2020.toFixed(2)} sq km, Pixels: ${result2020.count}`);

  if (area2020 < area1986) {
    console.log('A'); // Yes
  } else {
    console.log('B'); // No
  }
}

